bool RuleL158([[maybe_unused]] Item* p) {
    return (PumsaEq(p, -1, "2**"sv) && PumsaEq(p, -2, "1**"sv) && AttrMinusEq(p, -2, "VLq"sv));
}

// # 숫자와 기간 단위 뒤의 '間'을 '간'으로 고르고 사이의 'の'를 지우며 'との' 뒤에서는 '사이'로 바꾼다.
// local 159
