bool RuleL163([[maybe_unused]] Item* p) {
    return GramEq(p, 0, "Ow"sv);
}

// # かも는 知れな·しれな 또는 知れ·しれ 동사 앞에서 과거 추측형 ‘-었을지도’로 고른다.
// local 164
//     (src[+1] == "知れな" or src[+1] == "しれな") and pos[+1] is 7**
