           (SrcEq(p, 1, "です"sv) && PumsaEq(p, 1, "2**"sv)) ||
           ((SrcEq(p, -1, "これ"sv) ||
           SrcEq(p, -1, "あれ"sv) ||
           SrcEq(p, -1, "それ"sv)) && SrcEq(p, 1, "Lです"sv) && PumsaEq(p, 1, "2**"sv));
